-- 0015 · The first version of the terms, unapproved
--
-- Transcribed from the signed PDF the company has been sending, because that
-- PDF has no text layer — every page of it is an image, so every word here was
-- read off a picture by eye.
--
-- Which is exactly why is_approved is false. The template renders, a contract
-- cannot be issued from it, and create_contract_from_quote returns
-- 'no_approved_template' until a person has read it against the original and
-- said so. A transcription nobody proofread is a draft that happens to look
-- finished, and this is the one document where that difference is the whole
-- point.
--
-- Seven defects in the source text were found during transcription and are
-- deliberately reproduced rather than silently fixed: 5.3 and 5.4 are identical,
-- 2.8 says "מתחייב ללקוח" where it means "מתחייב הלקוח", 6.3(ח) is a truncated
-- sentence, 3.1 and 3.3 give two different service windows, and 3.0 is titled
-- for an insurance section that does not exist. Correcting a customer's contract
-- without being asked is not a transcription.

begin;

insert into public.contract_templates (version, title, sections, notes, is_approved, is_current)
values (
  1,
  'הסכם שירותי דיגיטל',
  $seed$[{"num": "1.0", "title": "כללי", "clauses": [{"num": "1.1", "text": "המבוא להסכם זה מהווה חלק בלתי נפרד הימנו."}, {"num": "1.2", "text": "חלוקתו של ההסכם לסעיפים, מתן כותרות לסעיפים, וסדר הסעיפים, נעשו לצורכי נוחות הקריאה בלבד, ואין להשתמש בהם לצורך פרשנות."}, {"num": "1.3", "text": "המזמין מצהיר בזה כי נציג החברה נתן לו הסבר מפורט על אופן פעולת המוצר, והשירות המסופק למוצר, והוא מסכים לתנאים כמפורט בהזמנה הנ״ל."}, {"num": "1.4", "text": "תקופת הסכם השירות הראשונית היא לשניים עשר חודשים, החל מתאריך אספקת העמדות/ הפצה לאוויר של האתר/ אפליקציית ההזמנות, **יובהר** כי התאריך אינו נקבע על פי תחילת השימוש של הלקוח במוצר, אלא על פי תאריך ההתקנה/ הפצה של המוצרים בפועל."}, {"num": "1.5", "text": "תקופת ההסכם תוארך באופן אוטומטי לתקופות נוספות של 12 חודשים כל פעם, אלא אם יודיע צד כלשהוא למשנהו לפחות 90 יום לפני מועד כל חידוש כאמור על רצונו בסיום ההסכם בתום אותה תקופה, וזאת בכתב בלבד באמצעות הדואר ו/או ע״י שליחת דוא״ל למייל של העדכני של החברה, לאחר ההודעה החברה תשיב ללקוח טופס התנתקות שעליו לחתום על מנת לנתק את השירותים בפועל, מובהר בזאת כי השירות ינותק רק בתנאי שהלקוח יחתום על טופס ההתנתקות."}, {"num": "1.6", "text": "החברה רשאית, בכל עת, לפי שיקול דעתה הבלעדי, להעביר ו/או לשעבד את זכויותיה בקשר למכשיר או התחייבויותיה או בקשר להסכם זה, כולן מקצתן לכל צד שלישי שהוא, ובלבד שזכויות הלקוח לפי הסכם זה לא יפגעו."}, {"num": "1.7", "text": "הלקוח מצהיר כי הוא בדק את המוצר באופן מקיף ויסודי ומצא אותו מתאים, עוד נבהיר כי השימוש הוא בפלטפורמה שמשמשת את כלל לקוחות החברה ואינה ניתנת לשינויים על פי רצון כלשהו של הלקוח, כמו כן החברה מעדכנת על פי שיקולה הבלעדי את המוצר לאורך הזמן."}, {"num": "1.8", "text": "הלקוח נותן בזאת לחברה בייט טכנולוגיה הרשאה בלתי חוזרת, להעביר קבצי מידע מהמוצר אשר אצל הלקוח למחשב ענן, לצורך גיבוי, ניתוח נתונים, ממשקים, כולל לצד שלישי כפי שחברת בייט טכנולוגיה תמצא לנכון."}, {"num": "1.9", "text": "גרסה התוכנה קבועה ואינה ניתנת לשינוי על כל מרכביה אלא אם צוין אחרת ע״י בייט טכנולוגיה."}, {"num": "1.10", "text": "על הלקוח לדאוג לתשתית אינטרנט וחשמל, ובנוסף התקנת כל תוכנה או כל חומרה או כל תשתית מתאימה אחרת כפי שיידרש ע״י חברת בייט טכנולוגיה."}, {"num": "1.11", "text": "החברה תתקין את המכשיר בבית העסק של הלקוח ו/או תריץ את התוכנה (המוצר) בתיאום מראש עם הלקוח. לפני מועד התקנת המכשיר, הלקוח ידאג להקצאת מקום מתאים בבית העסק ולקיומן התקין של נקודות חשמל וטלפון בקרבת נקודת ההתקנה ולכל תשתית נוספת התידרש על ידי החברה."}]}, {"num": "2.0", "title": "תשלום", "clauses": [{"num": "2.1", "text": "בעל הרישיון ישלם את דמי המנוי החלים, אשר אינם ניתנים להחזר בשום מקרה (להלן: ״דמי המנוי״) הנקובים בהצעת המחיר אשר הנפיקה בייט טכנולוגיה ו/או שותף שלה ו/או נציג מטעמה לשם קבלת רישיון לשימוש בתוכנה, במועדים ובתקופות המפורטים/ות בהצעה האמורה. בייט טכנולוגיה ו/או השותף שלה רשאים, מעת לעת, בהודעה לבעל הרישיון, לשנות ולעדכן את תעריפי המנוי ותעריפים אחרים בגין שירותים אחרים וזאת בהתראה של 30 ימים מראש. כמו כן, בהתאם להצעת המחיר, בעל הרישיון ישלם סכומים נוספים כגון, עלויות הקמת האפליקציה, הוצאות הקמת תפריט (צילום/עריכה/עיצוב), סכומים אלה אינם ניתנים להחזר בשום מקרה. בנוסף בעל הרישיון ישלם לחברה סכומים נוספים כפי שאלה יופיעו בהצעת המחיר כגון עמלות סליקה, תשלום חד פעמי עבור הזמנה, תשלום בגין שליחת מסרונים בשמו, וכן תשלומים נוספים אשר יידרש הלקוח לשלם בהתאם להצעת המחיר כאמור לעיל. אי עמידה בתנאי האשראי ו/או עיכוב בתשלומים לחברה יגררו ניתוק מידי של השירות."}, {"num": "2.2", "text": "בגין אי פירעון של חוב כל שהוא, חברת בייט טכנולוגיה שומרת לעצמה את הזכות להפסיק להעניק שירות, ותמיכה, למערכת שטרם נפרע מלוא החוב לחברה. כמו-כן החברה שומרת לעצמה את הזכות להסיר אפליקציה, אתר או כל מוצר דיגיטלי אחר מהרשת, וחשוב לציין כי הפסקת השירות אינה פוטרת את הלקוח מתשלומים כפי שהתחייב לחברה בהסכם זה."}, {"num": "2.3", "text": "כבטחון לביצוע והתחייבויותיו על-פי הסכם זה, יחתום הלקוח לנציג החברה על טופס ערבות אישית/שטר חוב."}, {"num": "2.4", "text": "בחתימה על מסמך הנ״ל אני מאשר לחברת בייט טכנולוגיה בע״מ לפרוע כל חוב באמצעות עסקה זכות במסוף אשראי של בית העסק. או בכל אמצעי תשלום שהלקוח מסר לחברת בייט טכנולוגיה בע״מ."}, {"num": "2.5", "text": "כל תשלום לפי הסכם זה יבוצע בתוספת מע״מ כשיעורו החוקי במועד התשלום."}, {"num": "2.6", "text": "פריטי הציוד של המוצר/שירות המוזמן יישארו בבעלות מלאה של בייט טכנולוגיה בע״מ עד לפירעון המלא של התשלומים."}, {"num": "2.7", "text": "הלקוח יחויב בתשלום בסך של 180 ש״ח על כל ביטול הוראה קבע בנק, או צ׳ק שאינו נפרע מכל סיבה שהיא."}, {"num": "2.8", "text": "במקרה של ביטול או הפרת הסכם ע״י הלקוח מתחייב הלקוח לשלם לחברת בייט טכנולוגיה פיצוי מוסכם מראש בסכום של מינימום 50% מגובה העסקה, במידה והחברה לא הקימה עדיין ממשק ללקוח. לאחר התחלת הקמת ממשק הלקוח מתחייב ללקוח לפצות את חברת בייט טכנולוגיה סכום של מינימום 75% מגובה העסקה."}, {"num": "2.9", "text": "המחירים הנקובים הן עבור עסקה של מינימום 12- חודשים, במידה והלקוח יבקש להפסיק את ההסכם לפני תום תקופת ההתחייבות יחויב במלוא התשלומים הנותרים בגין החומרה ובגין התשתיות כפול מספר החודשים עד לסיום תקופת ההתקשרות וכן עלויות בגין התשתית ובתוספת כל הטבה שניתנה ללקוח, באופן שכל החיובים יעמדו לתשלום לפירעון מיידי במועד ההתנתקות. לא ניתן לקבל זיכוי כספי במקרה של ביטול הסכם השירות לפני תום מועד השירות."}, {"num": "2.10", "text": "הלקוח יהיה רשאי להזמין מהספק מעת לעת לפי צרכיו שירותי פיתוח תוכנה של התאמות ושינויים וזאת בהתאם להצעת המחיר אשר תונפק במעמד הבקשה. החברה תבהיר כי לא כל סוג של פיתוח ניתן לביצוע על ידה ועל כן אינה מתחייבת לפתח עבור הלקוח תוספות ושינויים."}]}, {"num": "3.0", "title": "אמנת השירות וסוגי הביטוח", "clauses": [{"num": "3.1", "text": "שירותי התחזוקה יכללו תיקון שגיאות, תקלות ו״באגים״ במוצרים, תמיכה טלפונית לגבי אופן השימוש במוצרים, וכן אספקת והתקנת מהדורות/ גרסאות חדשות של המוצרים ככל שיפותחו לכלל הלקוחות ובהתאם למהדורה אשר הלקוח יבחר לרכוש את השימוש בה, כלומר, ייתכן כי החברה תפתח גרסה נוספת מתקדמת יותר לתוכנה ו/או לאפליקציה בעלות גבוהה יותר. הלקוח לא יהא מחויב להתקין ולהשתמש בכל מהדורה/גרסה חדשה, ואולם לצורך קבלת מלוא שירותי התחזוקה, יהא עליו לעבוד בכל עת עם הגרסה האחרונה של המוצרים או עם הגרסה שלפני האחרונה. המענה הטלפוני של החברה יפעל בימים א-ה בין השעות 10:00 ועד 16:00 באמצעותו ו/או ע״י גורם צד ג׳, בכל מקרה כל פנייה תטופל בתוך 3 ימי עסקים ע״י נציג החברה. שירותי האחזקה אינם כוללים תקלות שיגרמו מהתקנה ו/או הפעלת התוכנה שלא בהתאם להוראות הפעלה שנמסרו ללקוח על ידי החברה, ו/או כתוצאה משינוי התוכנה על ידי לקוח או מי מטעמו שלא באישור הספק. המזמין יקבל שירות או ביטוח לפי קבוצת התנאים שעליה סוכם מראש וצוינה בתהליך ההזמנה, המזמין מצהיר בזאת שהוסבר לו על התנאים בע״פ על ידי נציג החברה וכאמור בכתב."}, {"num": "3.2", "text": "ביקור טכנאי בבית העסק עבור טיפול בתקלה, יתואם וייקבע ע״י חברת בייט טכנולוגיה על פי סוג התקלה ורמת ההשבתה."}, {"num": "3.3", "text": "הספק יקבל קריאות שירות בימים א׳ עד ה׳ בין השעות 09:00 עד 18:00, ובימי ו׳ ובערבי חג בין השעות 09:00 עד 13:00 (להלן ״חלון השירות״)."}, {"num": "3.4", "text": "תחילת הטיפול בתקלה על ידי הספק תהיה לכל היתר תוך 48 שעות עסקים ממועד קבלת קריאת השירות."}, {"num": "3.5", "text": "הספק יטפל בכל תקלה בשקדנות ובמקצועיות, ויתקנה בתוך פרק זמן סביר בהתאם לאופי התקלה."}, {"num": "3.6", "text": "בזמן טיפול בתקלה יעמיד הלקוח לרשות הספק את כל המשאבים שידרשו לצורך השירות, לרבות גישה לתשתיות מחשוב רלוונטיות ומסירת כל מידע טכני."}, {"num": "3.7", "text": "בייט טכנולוגיה בע״מ רשאית להפסיק מדי פעם את השירות לשם: תחזוקה, תיקון, שדרוג ושיפור המערכות שהיא מפעילה ולא תהיה ללקוח כל טענה, תביעה או דרישה כלפי בייט טכנולוגיה בע״מ בגין ביצוע האמור לעיל או תקלות שיתרחשו עקב ביצועי עבודות תחזוקה."}, {"num": "3.8", "text": "**אחריות מוגבלת** - המוצר מסופק כפי שהוא (IS-AS) על ידי בייט טכנולוגיה לבעל הרישיון, ובייט טכנולוגיה וספקיה, ככל שישנם, אינם מעניקים כל אחריות, מכל סוג שהיא, מפורשת או משתמעת, על המוצר, ובפרט מתכחשים לכל אחריות לסחירות, בעלות, התאמה למטרה מסוימת ואי הפרה, במידה המרבית האפשרית על פי הדין. בייט טכנולוגיה אינה ערבה כי המוצר יעמוד בדרישות בעל הרישיון, יפעל ללא כל הפרעה או יהיה נטול שגיאות. בעל הרישיון מאשר כי כל שימוש במוצר, שיפורי המוצר, התאמות ושדרוגי תחזוקה יהיו באחריותו הבלעדית של בעל הרישיון. מבלי להגביל את האמור לעיל, בייט טכנולוגיה, ו/או חברות הבת שלה, ו/או ספקי הרישיונות שלה אינם ערבים כי כל מידע שנמסר לבעל הרישיון על ידי בייט טכנולוגיה הינו מדויק, אמין ונכון; כי כל פגמים או שגיאות במוצר יתוקנו; או כי המוצר הינו נקי מווירוסים ו/או רכיבים מזיקים אחרים. כל תוכן אשר מורד או מתקבל בדרך אחרת באמצעות השימוש במוצר הינו מורד באחריותו הבלעדית של בעל הרישיון, ובעל הרישיון יהא אחראי בלעדית בגין כל נזק לערכת הממוחשבת או כל אבדן נתונים שינבע מהורדה שכזו."}]}, {"num": "4.0", "title": "סודיות", "clauses": [{"num": "4.1", "text": "הצדדים מתחייבים לשמור בסודיות באופן בו הם שומרים על מידע סודי שלהם, כל מידע, ולגרום לכך שעובדיהם וכל האחרים הבאים מטעמם, ישמרו אף הם בסודיות כאמור לעיל, כל מידע כאמור. ״מידע״ לעניין סעיף זה על משמעו – כל מסמך , מידע, ידיעות, פרטים ונתונים מכל סוג שהוא, בעל פה או בכתב או בדרך אחרת, אודות הצד השני ו/או עובדיו ו/או לקוחותיו ו/או ספקיו, לרבות מידע בנוגע לשיטות עבודתו, תוכנות שלו, סודות מסחריים, נהלים, כללים, סידורי ביטחון, אבטחת מידע וכיו״ב, ואשר סומן כסודי, או שהצד המוסר מתייחס אליו כסודי, או שניתן להבין באופן סביר כי הוא סודי, וכן כל נתון אחר המוגן על פי דין (כגון חוק עוולות מסחריות, חוק הגנת הפרטיות וכד׳) אשר נמסרו או נחשפו תוך כדי ו/או עקב ביצוע הסכם זה."}, {"num": "4.2", "text": "מידע אשר הצד המקבל יוכיח כי הגיע או יגיע לידיו ממקורות אחרים, ללא הפרת חובת הסודיות של מקורות אלו."}, {"num": "4.3", "text": "מידע אשר הצד המקבל חייב לגלותו על פי דין (לרבות על פי צו בית המשפט) לגוף כלשהו."}, {"num": "4.4", "text": "מידע אשר הצד המקבל יוכיח כי הוא בגדר נחלת הכלל או שהפך לנחלת הכלל שלא עקב הפרת התחייבותו לסודיות."}, {"num": "4.5", "text": "ידע מקצועי של הצד המקבל ו/או מידע שפותח בידי הצד המקבל ו/או שנרכש על ידו תוך כדי ביצוע השירותים ו/או מתודולוגיות ושיטות עבודה הנוגעים באופן כללי לעיבוד נתונים ומחשוב."}, {"num": "4.6", "text": "יובהר בזאת כי על מנת להפעיל את השירות בצורה יעילה נבקש לקבל מבית העסק מידע אודות לקוחותיו, כמו כן יימצא במאגר החברה התפריט של בית העסק, מערך הפעילות אשר נוצרה מתוך שימוש בתוכנה ו/או באפליקציה, פרטים אישיים של בית העסק ושל מנהלי בית העסק וכל מידע נוסף אשר יגיע לחברה. הלקוח מודע לכך שהמידע נמצא ונשמר במאגרי המידע של החברה ומסכים לה לעשות בו כל שימוש מכל סוג שהוא לרבות שימוש מסחרי, העברת מידע לצד ג׳ ושימושים נוספים. כמו כן הלקוח מודע ומאפשר לחברה לנקוט בשמו בכל אמצעי שיווקי לרבות פרסומים ברחבי האינטרנט וכל מדיה נוספת, זאת כאמור בעיקר אך לא רק, לעודד את השימוש באפליקציה בקרב לקוחות בית העסק. בנוסף לאמור לעיל, הלקוח ייתן רשות להטמיע בחברות התקשורת צלצול בהמתנה אשר יופק עבור בית העסק ע״י החברה ו/או ע״י גורם צד ג׳ מטעמה. יובהר כי בית העסק מאשר לפרסם עבורו ברשתות המדיה החברתית כגון ״פייסבוק״ ובאתרי החיפוש למיניהם לרבות ״גוגל״ . כמו כן הלקוח מאשר לחברה לשלוח מסרונים ללקוחות בית העסק בשמו וליצור קשר עמם על פי שיקול דעתה הבלעדי."}]}, {"num": "5.0", "title": "שונות", "clauses": [{"num": "5.1", "text": "הלקוח מאשר כי ידוע לו כי כניסתו של הסכם זה לתוקף מותנה בקבלת אישור מנהלת החברה להתקשרות עמו, והיה ולא התקבל אישור מהנהלת החברה להתקשרות נשוא הסכם זה, מכל סיבה שהיא לא יהיה להסכם זה כל תוקף והמנוי מוותר בזאת על כל טענה ו/או תביעה כלפי החברה בגין כך."}, {"num": "5.2", "text": "על הצעה זו יחול הדין הישראלי בלבד. סמכות השיפוט הייחודית לפי הסכם זה מסורה לבתי המשפט במחוז חיפה בישראל, על פי בחירת בייט טכנולוגיה בע״מ."}, {"num": "5.3", "text": "הסכם זה מבטא את ההסכמה המלאה שבין הצדדים בקשר עם מכירת המוצר ולא יהיה תוקף לכל הסדר או מצג שלא קיבלו ביטוי מפורש בהסכם זה. כל שינוי בהסכם זה יהיה בכתב ובחתימת הצדדים."}, {"num": "5.4", "text": "הסכם זה מבטא את ההסכמה המלאה שבין הצדדים בקשר עם מכירת המוצר ולא יהיה תוקף לכל הסדר או מצג שלא קיבלו ביטוי מפורש בהסכם זה. כל שינוי בהסכם זה יהיה בכתב ובחתימת הצדדים."}, {"num": "5.5", "text": "הסכם זה על נספחיו ממצא את מלוא ההסכמה בין הלקוח לבין הספק ביחס לנושאים הנדונים בו, והוא מחליף ומבטל כל הסכם, מסמך, הבטחה או מצג קודמים בנוגע לנושאים אלה."}, {"num": "5.6", "text": "אני מבקש לקבל את החשבונית החודשית שלכם, כמסמך ממוחשב, בכתובת הדואר האלקטרוני המפורטת במסמך ההזמנה, ומאשר כי ברשותי האמצעים הטכנולוגים הדרושים לקבלת ושמירת החשבונית: אישור זה נעשה בהתאם להוראות סעיף 18ב׳ (ג) להוראות מס הכנסה (ניהול פנקסי חשבונות), התשל״ג – 1973 ויהיה בתוקף עד למועד ביטולו בהודעתי הכתובה אליכם.\\nמובהר כי שירות לשירות חשבונית מס בדואר אלקטרוני, מהווה הסכמה של המשתמש לקבל דואר אלקטרוני שמטרתם לעודד רכישת מוצר או שירות, אשר עשוי לכלול עדכונים בנושאים שונים, פרטים על ביצוע עסקה, פרסום וכיוצ״ב, ולרבות מסרים המכילים תוכן העונה להגדרה ״דבר פרסומת״, על פי תיקון 40 לחוק התקשורת (בזק ושידורים), התשמ״ב – 1982, הינך רשאי, בכל עת, להודיע לחברה על רצונך להסיר את כתובתך מרשימת הדיוור של החברה, ע״י יצירת קשר עם בייט טכנולוגיה"}]}, {"num": "6.0", "title": "מנוי למוצר", "clauses": [{"num": "6.1", "text": "החברה מציעה רישיון שימוש במערכת הזמנות משולבת אפליקציה לבית העסק, כפי שהוצגה ללקוח ואשר מכילה את המאפיינים אשר הוצגו ללקוח במהלך הפגישה ו/או השיחה. בכפוף לתשלום דמי המנוי המתאימים על ידי בעל הרישיון ובכפוף לתנאים אחרים בהסכם זה, בייט טכנולוגיה מעניקה לבעל הרישיון רישיון מוגבל, לא בלעדי, בלתי ניתן להעברה ולהמחאה, לצורך הפעלה, תצוגה ושימוש אחר במוצר לשם המטרות העסקיות הפנימיות של בעל הרישיון במהלך תקופת המנוי המתאימה. החברה מצהירה כי היא מחזיקה כדין במלוא הזכויות למתן הרשאות שימוש במוצרי התוכנה הידועה בשם ״בייט״ , מערכת הזמנות לבית העסק הכוללת אפשרות לאפליקציה ממותגת בשם בית העסק אשר מציגה את תפריט בית העסק (להלן ״המוצרים״), כמו כן החברה מצהירה כי יש בידה את הזכות המלאה להעניק ללקוח הרשאת שימוש בתוכנה ובאפליקציה, וכמו-כן שרותי אחזקה ופיתוח."}, {"num": "6.2", "text": "**פרטי הזדהות** — החברה תעניק לבעל הרישיון שם משתמש וסיסמא ייחודיים. עליך לשמור על פרטי ההזדהות בסודיות רבה, שכן , מקרה של גילוי הפרטים הללו עשוי לחשוף את בית העסק למזיקים ו/או האקרים למיניהם אשר עלולים לפגוע במהלך הפעילות התקינה של בית העסק. יובהר בזאת כי אין החברה אחראית על כל מקרה של חדירה למערכת ושל גילוי פרטי ההתחברות של הלקוח."}, {"num": "6.3", "text": "**הגבלת הרישיון** — לבעל הרישיון לא תהא כל זכות לבצע, ולא יבצע, או יורה או יסייע לאחרים לבצע, את האמור להלן: א. להעתיק את התיעוד; ב. לפרק, לבצע הנדוס לאחור, לשנות, לתרגם, להחליף או להדר לאחור, כל ו/או מקצת מהתוכנה, ו/או לחשוף בדרך אחרת את קוד המקור של התוכנה, זולת על פי ובמידה המותר/ת בדין החל בלבד, על אף הגבלה זו ; ג. לעשות שימוש בתוכנה על בסיס של לשכת שירות או על בסיס שיתוף זמנים או לספק שירותים לצדדים שלישיים; ד. להפיץ, להעתיק, להשכיר, להחכיר, להעניק רישיון משנה, להקצות, למסור, למכור או להעביר בכל דרך אחרת את המוצר או כל הזכויות של בעל הרישיון בו; ה. לעשות שימוש בשם, לוגו או סימנים מסחריים של בייט טכנולוגיה; ו. לפרסם תוצאות של כל השוואות או פעולות מדידה אחרות אשר בעל הרישיון יערוך עם התוכנה, לבד או בחיבור עם כל תוכנה או חומרה אחרת ללא הסכמה מראש ובכתב של בייט טכנולוגיה; ז. לעשות שימוש בתוכנה לפעילות בלתי חוקית; ח. להעביר באמצעות התוכנה חומרים אשר עלולים בשם רק על ידי אותו המשתמש בשם, וכי מספר אנשים לא יוכלו לחלוק את אותם פרטי התקשרות; ט. להודיע מידית לבייט טכנולוגיה בכתב במידה ו ״משתמש מורשה״ של בעל הרישיון משמעו עובד ו/או קבלן של בעל הרישיון אשר עובד באופן קבוע במקום העבודה של בעל הרישיון."}, {"num": "6.4", "text": "**זכויות קניין** — בעל הרישיון מאשר ומסכים כי המוצר מכיל מידע קנייני יהווה סוד מסחרי של בייט טכנולוגיה ו/או ספקי הרישיונות שלה. מלבד הרישיון המוגבל שניתן לבעל רישיון (לפי סעיף 1 לעיל), בייט טכנולוגיה וספקיה, באם ישנם, מחזיקים בכל זכויות הבעלות וזכויות הקניין והקניין הרוחני בתוך ועבור המוצר ובכל ומקצת השיפורים, עדכונים, שדרוגים, תיקונים, התאמות, תוצרים נגזרים, שינויים, גרסאות , הרחבות, שדרוגים, נוסחי שפה לאומיים, ו/או שיפורים שלהם, כולם בין אם נעשו, נוצרו או פותחו על ידי בייט טכנולוגיה ו/או כל צד שלישי אחר."}]}, {"num": "7.0", "title": "התקנה", "clauses": [{"num": "7.0", "text": "התקנה והיישומון מאפשרים תשלום בכרטיס אשראי, מכיוון שהתשלום מוגדר כ-סליקה מקוונת (רכישות און-ליין) על בית העסק להתחבר לשירות המתאים לכך."}]}]$seed$::jsonb,
